package com.bocsoft.sqleditor.export;
import com.bocsoft.sqleditor.auth.*;import com.bocsoft.sqleditor.common.RequestIds;import com.bocsoft.sqleditor.export.api.SqlExportRequest;import java.nio.charset.StandardCharsets;import javax.servlet.http.HttpServletRequest;import javax.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody;
@RestController @RequestMapping("/api/v1/sql/exports") public class CsvExportController {private final CsvExportService service;public CsvExportController(CsvExportService service){this.service=service;}@PostMapping(produces="text/csv")public ResponseEntity<StreamingResponseBody>export(@Valid @RequestBody SqlExportRequest request,HttpServletRequest servlet){CsvExportService.PreparedExport p=service.prepare(CurrentAuth.get(),request,String.valueOf(servlet.getAttribute(RequestIds.ATTRIBUTE)));ContentDisposition disposition=ContentDisposition.attachment().filename(p.getFilename(),StandardCharsets.UTF_8).build();return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,disposition.toString()).contentType(new MediaType("text","csv",StandardCharsets.UTF_8)).body(p.getBody());}}
